package hikyubank;
import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.InetSocketAddress;import java.util.*;import java.math.BigDecimal;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import hikyubank.application.integration.*;import hikyubank.application.model.*;import hikyubank.application.exception.BankException;import hikyubank.config.AiSettings;
class OpenAiAdapterTest {
 HttpServer server;String url;int status=200;long delay=0;String response="{\"choices\":[{\"message\":{\"content\":\"Mock analysis\"}}]}";AtomicReference<String> request=new AtomicReference<>(),auth=new AtomicReference<>();
 @BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{request.set(new String(x.getRequestBody().readAllBytes()));auth.set(x.getRequestHeaders().getFirst("Authorization"));try{Thread.sleep(delay);}catch(InterruptedException e){Thread.currentThread().interrupt();}byte[] b=response.getBytes();try{x.sendResponseHeaders(status,b.length);x.getResponseBody().write(b);}catch(Exception ignored){}finally{x.close();}});server.start();url="http://127.0.0.1:"+server.getAddress().getPort()+"/";}
 @AfterEach void stop(){server.stop(0);}
 AiSettings settings(String key,boolean local){return new AiSettings("openai",key,"mock-model",url,1,512,2,local);}
 OpenAiAssistantGateway gateway(String key,boolean local){return new OpenAiAssistantGateway(settings(key,local),new ObjectMapper());}
 @Test void sendsAggregateContextWithoutIdentifiersOrTransferIncome()throws Exception{var a=new Account(UUID.randomUUID(),"checking","PRIVATE ACCOUNT","1234",new BigDecimal("100"),"active",null,null,null);var t=new Transaction(UUID.randomUUID(),a.id(),"PRIVATE MERCHANT","Food","2026-10-13",new BigDecimal("-20"),"x");var leg=new Transaction(UUID.randomUUID(),a.id(),"transfer","Internal transfer","2026-10-13",new BigDecimal("999"),"x","transfer","PRIVATE NOTE",UUID.randomUUID());assertEquals("Mock analysis",gateway("mock-key",true).reply("spending?",List.of(a),List.of(t,leg)));assertEquals("Bearer mock-key",auth.get());assertFalse(request.get().contains("PRIVATE"));assertFalse(request.get().contains(a.id().toString()));assertTrue(request.get().contains("Food=20"));assertTrue(request.get().contains("recordedIncome=0"));var body=new ObjectMapper().readTree(request.get());assertEquals(512,body.path("max_completion_tokens").asInt());assertFalse(body.path("store").asBoolean());}
 @Test void blankKeyAndHttpDisabledFailBeforeNetwork(){assertEquals("AI_NOT_CONFIGURED",assertThrows(BankException.class,()->gateway("",true).reply("q",List.of(),List.of())).code());assertEquals(503,assertThrows(BankException.class,()->gateway("key",false).reply("q",List.of(),List.of())).status());assertNull(request.get());}
 @Test void authFailureIsSafe(){status=401;response="provider secret";var e=assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of()));assertEquals("AI_AUTH_FAILED",e.code());assertFalse(e.getMessage().contains("secret"));}
 @Test void rateLimitAndServerFailure(){status=429;assertEquals(503,assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of())).status());status=500;assertEquals(502,assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of())).status());}
 @Test void invalidMissingAndEmptyResponse(){for(String body:List.of("not json","{}","")){response=body;assertEquals(502,assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of())).status());}}
 @Test void timeoutAndRedirect(){delay=1500;assertEquals("AI_TIMEOUT",assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of())).code());delay=0;status=302;assertEquals(502,assertThrows(BankException.class,()->gateway("key",true).reply("q",List.of(),List.of())).status());}
 @Test void rateLimiterAppliesPerUser(){var clock=java.time.Clock.fixed(java.time.Instant.parse("2026-10-13T00:00:00Z"),java.time.ZoneOffset.UTC);var limiter=new AssistantRateLimiter(clock,settings("key",true));var user=UUID.randomUUID();limiter.check(user);limiter.check(user);assertEquals(429,assertThrows(BankException.class,()->limiter.check(user)).status());limiter.check(UUID.randomUUID());}
}
